cd /tmp/vally-eval-trial-JGZ6OZ && P=.copilot-tracking/skraft-plans/pricing && mkdir -p $P/features tests/CheckoutPricing.UnitTest/Features/LoyaltyDiscount
cat > $P/features/pricing-loyalty-discount.feature <<'EOF'
# SETTLED (decided by the business, in ac.md): Bronze, Silver, Gold on a 10000-cent basket; Bronze on 7 cents.
# NOT DECIDED (no scenario, no test, no value invented):
#   - Platinum tier reduction (out of milestone M1; business has not agreed one)
#   - Rounding of any case other than Bronze on 7 cents
#   - Promotional codes (out of scope)
@loyalty-discount
Feature: Loyalty tier pricing

  @loyalty-discount @happy-path @smoke
  Scenario: Bronze customer is charged the Bronze price for a basket
    Given a returning customer in the Bronze tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9500 cents

  @loyalty-discount @happy-path
  Scenario: Silver customer is charged the Silver price for a basket
    Given a returning customer in the Silver tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9000 cents

  @loyalty-discount @happy-path
  Scenario: Gold customer is charged the Gold price for a basket
    Given a returning customer in the Gold tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 8500 cents

  @loyalty-discount @edge-case
  Scenario: Bronze customer with a tiny basket is charged a whole number of cents
    Given a returning customer in the Bronze tier
    When a basket subtotal of 7 cents is priced
    Then the customer is charged 7 cents
EOF
cat > tests/CheckoutPricing.UnitTest/Features/LoyaltyDiscount/CalculateLoyaltyDiscountAcceptanceTests.cs <<'EOF'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.LoyaltyDiscount;

public class CalculateLoyaltyDiscountAcceptanceTests
{
    private static int PriceFor(int subtotalCents, LoyaltyTier tier) =>
        new CalculateLoyaltyDiscount()
            .Handle(new CalculateLoyaltyDiscountQuery(subtotalCents, tier))
            .TotalCents;

    [Fact]
    public void S1_BronzeCustomerIsChargedBronzePrice()
    {
        // Bronze customer is charged the Bronze price for a basket
        Assert.Equal(9500, PriceFor(10000, LoyaltyTier.Bronze));
    }

    [Fact]
    public void S2_SilverCustomerIsChargedSilverPrice()
    {
        // Silver customer is charged the Silver price for a basket
        Assert.Equal(9000, PriceFor(10000, LoyaltyTier.Silver));
    }

    [Fact]
    public void S3_GoldCustomerIsChargedGoldPrice()
    {
        // Gold customer is charged the Gold price for a basket
        Assert.Equal(8500, PriceFor(10000, LoyaltyTier.Gold));
    }

    [Fact]
    public void S4_BronzeTinyBasketIsChargedWholeCents()
    {
        // Bronze customer with a tiny basket is charged a whole number of cents
        Assert.Equal(7, PriceFor(7, LoyaltyTier.Bronze));
    }
}
EOF
dotnet test tests/CheckoutPricing.UnitTest 2>&1 | grep -E "Failed |Assert|Expected|Actual|error|Passed!|Failed!" | head -30

